CREATE COLUMN TABLE "TEST_AP"."@QC_CHAR_TYPE" ("Code" NVARCHAR(50) NOT NULL , "Name" NVARCHAR(100), "DocEntry" INTEGER CS_INT NOT NULL , "Canceled" NVARCHAR(1) DEFAULT 'N', "Object" NVARCHAR(20), "LogInst" INTEGER CS_INT, "UserSign" INTEGER CS_INT, "Transfered" NVARCHAR(1) DEFAULT 'N', "CreateDate" LONGDATE CS_LONGDATE, "CreateTime" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "UpdateTime" SMALLINT CS_INT, "DataSource" NVARCHAR(1), PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "KQC_CHAR_TYPE_IK" ON "TEST_AP"."@QC_CHAR_TYPE" ( "DocEntry" ASC )